/* KOLVIKA · подмена заголовка первого экрана под запрос из Яндекс Директа.
   Читает utm_term (в Директе: utm_term={keyword}) и, если ключ не распознан
   или пришёл автотаргетинг, параметр h (код группы, задаётся в ссылке объявления).
   Подставляет заранее написанный короткий заголовок — сам запрос в текст не вставляется.
   Выбранное правило уходит в Метрику параметром визита dynamic_title. */
(function () {
  "use strict";
  var COUNTER_ID = 112938684;
  var path = location.pathname;
  var page = /\/repair\/?/.test(path) ? "repair" : (/\/quiz\/?/.test(path) ? "quiz" : "main");

  // [код, регулярка по запросу, заголовок (HTML), подзаголовок или null]
  var MAKE = [
    ["own-gold", /из сво|переплав|передел|из стар|из бабушк|из лома|копи[юя] украш/, "Украшение<br><em>из вашего золота</em>",
      "Переплавим ваш металл и сделаем новое кольцо, серьги или цепочку. Ювелир оценит вес и пробу и заранее согласует стоимость."],
    ["engagement", /помолвоч/, "Помолвочное кольцо<br><em>на заказ</em>",
      "Подберём камень и форму, подготовим 3D-модель и согласуем стоимость до начала работы."],
    ["wedding", /обручальн|парные кольц|парных колец/, "Обручальные кольца<br><em>на заказ</em>",
      "Сделаем парные кольца по вашему эскизу или идее — из вашего или нашего золота."],
    ["earrings", /серьг|серёж|сереж|пусет|моносерьг/, "Серьги<br><em>на заказ</em>",
      "Изготовим серьги по фотографии, эскизу или вашей идее — с вашими или нашими камнями и металлом."],
    ["signet", /печатк|перст/, "Перстень и печатка<br><em>на заказ</em>",
      "Сделаем перстень или печатку по вашему эскизу — из золота или серебра, с вашим или нашим камнем."],
    ["pendant", /кулон|подвес|медальон/, "Кулон<br><em>на заказ</em>",
      "Изготовим кулон или медальон по фотографии, эскизу или вашей идее."],
    ["cross", /крест/, "Крестик<br><em>на заказ</em>",
      "Сделаем нательный крестик из золота или серебра по вашему эскизу."],
    ["bracelet", /браслет/, "Браслет<br><em>на заказ</em>",
      "Изготовим браслет по фотографии, эскизу или вашей идее — из вашего или нашего металла."],
    ["chain", /цеп/, "Цепочка<br><em>на заказ</em>",
      "Сделаем цепочку нужной длины и плетения — из вашего или нашего золота."],
    ["ring", /кольц|колец|колеч/, "Кольцо<br><em>на заказ</em>",
      "Изготовим кольцо по фотографии, эскизу или вашей идее — с вашими или нашими камнями и металлом."],
    ["sketch", /эскиз|фото|картинк|рисунк|дизайн/, "Украшение<br><em>по вашему эскизу</em>", null],
    ["silver", /серебр/, "Украшения из серебра<br><em>на заказ</em>", null],
    ["gold", /золот/, "Украшения из золота<br><em>на заказ</em>", null]
  ];
  var REPAIR = [
    ["remake", /переплав|передел|из сво|реставр|советск|винтаж|старин/, "Переделка<br><em>и реставрация украшений</em>",
      "Обновим дизайн или создадим новое украшение из вашего металла, сохранив важные детали."],
    ["chain-repair", /цеп|браслет|замок|замочек|звен/, "Ремонт<br><em>цепочек и браслетов</em>",
      "Спаяем звено, заменим замок, укоротим или удлиним цепочку. Мастер осмотрит украшение и назовёт стоимость."],
    ["resize", /размер|увелич|уменьш|расшир|растян|расточ|сузит/, "Изменим<br><em>размер кольца</em>",
      "Увеличим или уменьшим кольцо из золота и серебра. Мастер осмотрит кольцо и назовёт стоимость."],
    ["stones", /камн|камен|вставк|вставит|закреп/, "Замена и закрепка<br><em>камней</em>",
      "Подберём камень взамен утраченного и надёжно закрепим его в оправе."],
    ["polish", /чистк|почист|полир|шлиф|родир|царапин/, "Чистка<br><em>и полировка украшений</em>", null],
    ["solder", /пайк|спаят|спая|лопнул|сломал|порвал/, "Пайка<br><em>ювелирных изделий</em>", null],
    ["ring-repair", /кольц|колец/, "Ремонт<br><em>колец</em>", null],
    ["silver-repair", /серебр/, "Ремонт<br><em>серебряных украшений</em>", null],
    ["gold-repair", /золот/, "Ремонт<br><em>золотых украшений</em>", null]
  ];
  var rules = page === "repair" ? REPAIR : MAKE;

  function param(name) {
    try { return (new URLSearchParams(location.search).get(name) || "").toLowerCase().replace(/ё/g, "е"); }
    catch (e) { return ""; }
  }

  function pick() {
    var kw = param("utm_term") || param("kw");
    if (kw && kw.indexOf("autotargeting") === -1) {
      kw = kw.replace(/[+!"\[\]]/g, " ");
      for (var i = 0; i < rules.length; i++) if (rules[i][1].test(kw)) return rules[i];
    }
    var code = param("h");
    for (var j = 0; j < rules.length; j++) if (rules[j][0] === code) return rules[j];
    return null;
  }

  function apply() {
    var rule = pick();
    if (!rule) return;
    var h1 = document.querySelector(".hero h1");
    if (!h1) return;
    h1.innerHTML = rule[2];
    var sub = document.querySelector(".hero .hero-copy > p:not(.eyebrow)");
    if (sub && page === "quiz") sub.textContent = "Ответьте на 5 вопросов — пришлём варианты и стоимость изготовления в течение дня.";
    else if (sub && rule[3]) sub.textContent = rule[3];
    if (typeof window.ym === "function") {
      try { window.ym(COUNTER_ID, "params", { dynamic_title: page + ":" + rule[0] }); } catch (e) {}
    }
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", apply); else apply();
})();
